static int roundUpToMultipleOf4(int n)
{
	return (n + 3) & ~3;
}

// Frames are split into horizontal bands of 4x4-block rows and encoded on all cores
// (parallel.hpp). Every block depends only on its own 16 pixels, so the output is
// identical to single-threaded encoding.
static const int kBlockRowsPerBand = 8;

static int bandCount(int height)
{
	const int blockRows = (height + 3) / 4;
	return (blockRows + kBlockRowsPerBand - 1) / kBlockRowsPerBand;
}

// texture conversion from adobe-preferred to hap_encode required
// these converters all use squish as the final stage
class SquishTextureConverter : public TextureConverter
{
public:
	SquishTextureConverter(const FrameSize& frameSize, int squishFlags)
		: TextureConverter(frameSize), squishFlags_(squishFlags)
	{}
	virtual ~SquishTextureConverter() {};

private:
    size_t size() const override
    {
        return squish::GetStorageRequirements(frameSize().width, frameSize().height, squishFlags_);
    }

	virtual void doConvert(
		const uint8_t* in_rgba,
		std::vector<uint8_t> &ycocg,
		std::vector<uint8_t> &outputBuffer) override
	{
		const int w = frameSize().width, h = frameSize().height;
		outputBuffer.resize(size());
		const size_t bytesPerBlockRow = squish::GetStorageRequirements(w, 4, squishFlags_);
		uint8_t* out = outputBuffer.data();

		parallelFor(bandCount(h), [&](int band) {
			const int y0 = band * kBlockRowsPerBand * 4;
			const int bandHeight = std::min(kBlockRowsPerBand * 4, h - y0);
			squish::CompressImage(in_rgba + size_t(y0) * w * 4, w, bandHeight,
			                      out + size_t(y0 / 4) * bytesPerBlockRow, squishFlags_, nullptr);
		});
	}

	int squishFlags_;
};


class TextureConverterToYCoCg_Dxt5 : public TextureConverter
{
public:
	TextureConverterToYCoCg_Dxt5(const FrameSize& frameSize) : TextureConverter(frameSize) {}
	~TextureConverterToYCoCg_Dxt5() {}

    size_t size() const override
    {
        return roundUpToMultipleOf4(frameSize().width) * roundUpToMultipleOf4(frameSize().height);
    }

    void doConvert(
		const uint8_t* in_rgba,
		std::vector<uint8_t> &ycocg,
		std::vector<uint8_t> &outputBuffer) override
	{
		const int w = frameSize().width, h = frameSize().height;
		const int rowbytes = w * 4;
		ycocg.resize(size_t(rowbytes) * h);
		outputBuffer.resize(size());
		const size_t bytesPerBlockRow = size_t(roundUpToMultipleOf4(w)) * 4;   // 16 bytes per 4x4 block

		parallelFor(bandCount(h), [&](int band) {
			const int y0 = band * kBlockRowsPerBand * 4;
			const int bandHeight = std::min(kBlockRowsPerBand * 4, h - y0);
			uint8_t* ycocgBand = &ycocg[size_t(y0) * rowbytes];

			ConvertRGB_ToCoCg_Y8888(
				in_rgba + size_t(y0) * rowbytes, // const uint8_t *src,
				ycocgBand,                       // uint8_t *dst
				w,                               // unsigned long width,
				bandHeight,                      // unsigned long height,
				rowbytes,                        // size_t src_rowbytes
				rowbytes,                        // size_t dst_rowbytes,
				false                            // int allow_tile
			);

			CompressYCoCgDXT5(
				ycocgBand,
				&outputBuffer[size_t(y0 / 4) * bytesPerBlockRow],
				w, bandHeight,
				rowbytes  // stride
			);
		});
	}
};


// Hap R: RGBA -> BC7 (BPTC_UNORM) using bc7e (Binomial LLC, Apache 2.0), compiled with Intel ISPC
// for ARM NEON (Apple Silicon) and SSE4/AVX2 (x64). Quality presets were chosen by measurement so
// each setting is at least as good as the previous bc7enc-based encoder at the same setting:
//   Fast -> bc7e "veryfast", Normal -> "basic", High -> "slow".


// 1.2.1: which bc7e build to run. ISPC's own dispatch picks the widest the CPU has, which on AMD
// Zen 4 (Threadripper 7000) is AVX-512 - measured ~10% slower there than AVX2 (Zen 4 runs AVX-512
// on 256-bit units and its gathers are slow). So AMD CPUs use the AVX2 build; Intel keeps AVX-512
// (25-33% faster than AVX2 in our tests). PPHAP_SIMD=avx2|avx512|auto overrides. Same quality.
#if (defined(_M_X64) || defined(__x86_64__)) && !defined(__aarch64__) && !defined(_M_ARM64)
#define PP_BC7E_X64 1
#ifdef _MSC_VER
#include <intrin.h>
#else
#include <cpuid.h>
#endif
#include <cstdlib>
extern "C" {
void bc7e_compress_block_init_avx2();
void bc7e_compress_blocks_avx2(uint32_t, uint64_t*, const uint32_t*, const ispc::bc7e_compress_block_params*);
void bc7e_compress_block_init_avx512skx();
void bc7e_compress_blocks_avx512skx(uint32_t, uint64_t*, const uint32_t*, const ispc::bc7e_compress_block_params*);
}
static void cpuidex(int leaf, int sub, unsigned r[4])
{
#ifdef _MSC_VER
	int t[4]; __cpuidex(t, leaf, sub); for (int i = 0; i < 4; ++i) r[i] = unsigned(t[i]);
#else
	__cpuid_count(leaf, sub, r[0], r[1], r[2], r[3]);
#endif
}
static unsigned long long xgetbv0()
{
#ifdef _MSC_VER
	return _xgetbv(0);
#else
	unsigned lo, hi; __asm__ volatile("xgetbv" : "=a"(lo), "=d"(hi) : "c"(0)); return (unsigned long long)hi << 32 | lo;
#endif
}
#endif

typedef void (*Bc7eCompressFn)(uint32_t, uint64_t*, const uint32_t*, const ispc::bc7e_compress_block_params*);
static Bc7eCompressFn g_bc7eCompress = nullptr;
static const char* g_bc7eName = "auto";

static void bc7eDispatch(uint32_t n, uint64_t* out, const uint32_t* px, const ispc::bc7e_compress_block_params* p)
{
	ispc::bc7e_compress_blocks(n, out, px, p);
}

static void chooseBc7e()
{
	g_bc7eCompress = bc7eDispatch;
	ispc::bc7e_compress_block_init();
#ifdef PP_BC7E_X64
	unsigned r[4];
	cpuidex(0, 0, r);
	char vendor[13] = {};
	memcpy(vendor, &r[1], 4); memcpy(vendor + 4, &r[3], 4); memcpy(vendor + 8, &r[2], 4);
	const unsigned maxLeaf = r[0];
	cpuidex(1, 0, r);
	const bool osxsave = (r[2] >> 27) & 1, avx = (r[2] >> 28) & 1;
	bool avx2 = false, avx512 = false;
	if (osxsave && avx && maxLeaf >= 7) {
		const unsigned long long xcr0 = xgetbv0();
		cpuidex(7, 0, r);
		avx2 = ((xcr0 & 6) == 6) && ((r[1] >> 5) & 1);
		// avx512skx = F + CD + BW + DQ + VL, with the OS saving the opmask / ZMM state
		const unsigned skx = (1u << 16) | (1u << 28) | (1u << 30) | (1u << 17) | (1u << 31);
		avx512 = avx2 && ((xcr0 & 0xE6) == 0xE6) && ((r[1] & skx) == skx);
	}
	std::string want;
	if (const char* e = getenv("PPHAP_SIMD")) want = e;
	if (want.empty()) want = (!strcmp(vendor, "AuthenticAMD") && avx512) ? "avx2" : "auto";
	if (want == "avx2" && avx2) { bc7e_compress_block_init_avx2(); g_bc7eCompress = bc7e_compress_blocks_avx2; g_bc7eName = "avx2"; }
	else if (want == "avx512" && avx512) { bc7e_compress_block_init_avx512skx(); g_bc7eCompress = bc7e_compress_blocks_avx512skx; g_bc7eName = "avx512"; }
	else g_bc7eName = avx512 ? "avx512" : avx2 ? "avx2" : "sse4";   // ISPC's own dispatch picks the best one
#endif
}

const char* bc7eSimdName() { return g_bc7eName; }

// RGB error metric (perceptual = false): measured against Jokyo Hap R (Fast vs Fast, 4K test clip)
// it is better on both RGB (+1.3 dB) and luma (+1.1 dB); perceptual mode was faster but lost on RGB.
class TextureConverterToBC7 : public TextureConverter
{
public:
	TextureConverterToBC7(const FrameSize& frameSize, SquishEncoderQuality quality)
		: TextureConverter(frameSize), quality_(quality)
	{
		static std::once_flag initOnce;
		std::call_once(initOnce, []() { chooseBc7e(); });

		const bool perceptual = false;
		switch (quality)
		{
		case kSquishEncoderFastQuality:
			ispc::bc7e_compress_block_params_init_veryfast(&params_, perceptual);
			break;
		case kSquishEncoderBestQuality:
			ispc::bc7e_compress_block_params_init_slow(&params_, perceptual);
			break;
		default:
			ispc::bc7e_compress_block_params_init_basic(&params_, perceptual);
			break;
		}
	}
	~TextureConverterToBC7() {}

	size_t size() const override
	{
		return (size_t)blocksWide() * blocksHigh() * 16;
	}

private:
	int blocksWide() const { return (frameSize().width + 3) / 4; }
	int blocksHigh() const { return (frameSize().height + 3) / 4; }

	void doConvert(
		const uint8_t* in_rgba,
		std::vector<uint8_t>& /*ycocg*/,
		std::vector<uint8_t>& outputBuffer) override
	{
		outputBuffer.resize(size());
		// 1.2.0: the GPU encoder, for the Fast setting (the default) only: it is more accurate than the
		// CPU's Fast on every test clip, but not more accurate than Normal / High
		if (quality_ == kSquishEncoderFastQuality && gpubc7::mode() != gpubc7::Mode::Off) {
			const uint8_t* padded = paddedFrame(in_rgba);
			if (useGpu(padded) && gpubc7::encode(padded, blocksWide() * 4, blocksHigh() * 4, outputBuffer.data()))
				return;
		}
		encodeCpu(in_rgba, outputBuffer.data());
	}

	// the frame padded to whole 4x4 blocks by repeating the last column / row (as the CPU path does).
	// One converter serves frames encoded on several threads at once, so the buffer is per thread.
	const uint8_t* paddedFrame(const uint8_t* in_rgba)
	{
		const int w = frameSize().width, h = frameSize().height, pw = blocksWide() * 4, ph = blocksHigh() * 4;
		if (pw == w && ph == h) return in_rgba;
		thread_local std::vector<uint8_t> padded_;
		padded_.resize(size_t(pw) * ph * 4);
		for (int y = 0; y < ph; ++y) {
			const uint8_t* src = in_rgba + size_t(std::min(y, h - 1)) * w * 4;
			uint8_t* dst = &padded_[size_t(y) * pw * 4];
			memcpy(dst, src, size_t(w) * 4);
			for (int x = w; x < pw; ++x) memcpy(dst + size_t(x) * 4, src + size_t(w - 1) * 4, 4);
		}
		return padded_.data();
	}

	// Auto: before the first frame, time the GPU against an estimate of the CPU (one band on one
	// thread, scaled to the frame and the cores) and keep the faster one for the rest of the session.
	// Both are timed on the same built-in test picture (gradients + noise), not on the first frame,
	// which is often black and far quicker on the CPU than typical frames. On: always the GPU.
	bool useGpu(const uint8_t* /*padded*/)
	{
		if (!gpubc7::available()) {
			static std::once_flag noted;
			if (gpubc7::mode() == gpubc7::Mode::On)
				std::call_once(noted, [] { fprintf(stderr, "pphap: GPU encoding not available (%s); using the CPU\n", gpubc7::description().c_str()); });
			return false;
		}
		if (gpubc7::mode() != gpubc7::Mode::Auto) return true;
		static std::once_flag decided;
		static std::atomic<bool> gpuFaster{ false };
		std::call_once(decided, [&] {
			const int pw = blocksWide() * 4, ph = blocksHigh() * 4;
			std::vector<uint8_t> scratch(size());
			std::vector<uint8_t> test(size_t(pw) * ph * 4);
			uint32_t seed = 12345u;
			for (int y = 0; y < ph; ++y)
				for (int x = 0; x < pw; ++x) {
					seed = seed * 1664525u + 1013904223u;
					uint8_t* p = &test[(size_t(y) * pw + x) * 4];
					p[0] = uint8_t(x * 255 / std::max(1, pw - 1));
					p[1] = uint8_t(y * 255 / std::max(1, ph - 1));
					p[2] = uint8_t(96 + ((seed >> 24) & 63));
					p[3] = 255;
				}
			const uint8_t* padded = test.data();
			using clock = std::chrono::steady_clock;
			gpubc7::encode(padded, pw, ph, scratch.data());   // first use also compiles the shader
			auto t0 = clock::now();
			const bool ok = gpubc7::encode(padded, pw, ph, scratch.data());
			const double gpuMs = std::chrono::duration<double, std::milli>(clock::now() - t0).count();
			// CPU: 16 block rows from the middle of the frame on this thread
			const int bh = blocksHigh(), rows = std::min(bh, 16), first = (bh - rows) / 2;
			t0 = clock::now();
			encodeCpuRows(padded, pw, first, first + rows, scratch.data());
			const double bandMs = std::chrono::duration<double, std::milli>(clock::now() - t0).count();
			// hardware threads count as ~0.6 of a core each (SMT); generous to the CPU, so the GPU is
			// only chosen when it is clearly faster
			const double cores = std::max(1.0, 0.6 * double(std::max(1u, std::thread::hardware_concurrency())));
			const double cpuMs = bandMs * double(bh) / double(rows) / cores;
			gpuFaster = ok && gpuMs < cpuMs;
			fprintf(stderr, "pphap: Hap R encoder: %s - GPU %s %.1f ms/frame, CPU about %.1f ms/frame\n",
			        gpuFaster ? "GPU" : "CPU", gpubc7::description().c_str(), gpuMs, cpuMs);
		});
		return gpuFaster;
	}

	void encodeCpu(const uint8_t* in_rgba, uint8_t* out)
	{
		const int w = frameSize().width, h = frameSize().height;
		const int bw = blocksWide(), bh = blocksHigh();
		(void)h;
		parallelFor(bandCount(h), [&](int band) {
			const int by0 = band * kBlockRowsPerBand;
			const int by1 = std::min(bh, by0 + kBlockRowsPerBand);
			std::vector<uint32_t> pixels(size_t(bw) * 16);   // one row of blocks, block-ordered RGBA
			for (int by = by0; by < by1; ++by)
			{
				for (int bx = 0; bx < bw; ++bx)
				{
					uint32_t* dst = &pixels[size_t(bx) * 16];
					// gather 4x4, clamping at right/bottom edges for non-multiple-of-4 sizes
					for (int py = 0; py < 4; ++py)
					{
						const int sy = std::min(by * 4 + py, h - 1);
						for (int px = 0; px < 4; ++px)
						{
							const int sx = std::min(bx * 4 + px, w - 1);
							memcpy(dst + py * 4 + px, in_rgba + (size_t(sy) * w + sx) * 4, 4);
						}
					}
				}
				g_bc7eCompress(bw, reinterpret_cast<uint64_t*>(out + size_t(by) * bw * 16),
				                           pixels.data(), &params_);
			}
		});
	}

	// rows [by0, by1) of an already padded frame, on this thread (for the CPU/GPU timing)
	void encodeCpuRows(const uint8_t* padded, int pw, int by0, int by1, uint8_t* out)
	{
		const int bw = pw / 4;
		std::vector<uint32_t> pixels(size_t(bw) * 16);
		for (int by = by0; by < by1; ++by) {
			for (int bx = 0; bx < bw; ++bx)
				for (int py = 0; py < 4; ++py)
					memcpy(&pixels[size_t(bx) * 16 + py * 4], padded + (size_t(by * 4 + py) * pw + bx * 4) * 4, 16);
			g_bc7eCompress(bw, reinterpret_cast<uint64_t*>(out + size_t(by) * bw * 16), pixels.data(), &params_);
		}
	}

	SquishEncoderQuality quality_;
	ispc::bc7e_compress_block_params params_;
};


