static std::unique_ptr<TextureConverter> createLegacy(const FrameSize& frameSize, unsigned int destFormat, SquishEncoderQuality quality);

// 1.1: the accurate encoders are the default; the 1.0.0 encoders below stay available unchanged
// (pphap -engine legacy, or PPHAP_ENGINE=legacy) and are also the fallback for any format the
// accurate engine does not handle (Hap R uses the same bc7e converter in both).
std::unique_ptr<TextureConverter> TextureConverter::create(const FrameSize& frameSize, unsigned int destFormat, SquishEncoderQuality quality)
{
	std::unique_ptr<TextureConverter> c;
	if (textureEngine() == TextureEngine::Accurate)
		c = createAccurateTextureConverter(frameSize, destFormat, int(quality));
	if (!c)
		c = createLegacy(frameSize, destFormat, quality);
	c->format_ = destFormat;
	return c;
}

static std::unique_ptr<TextureConverter> createLegacy(const FrameSize& frameSize, unsigned int destFormat, SquishEncoderQuality quality)
{
	int flag_quality;
	switch (quality)
	{
	case kSquishEncoderFastQuality:
		flag_quality = squish::kColourRangeFit;
		break;
	case kSquishEncoderBestQuality:
		flag_quality = squish::kColourIterativeClusterFit;
		break;
	default:
		flag_quality = squish::kColourClusterFit;
		break;
	}

	switch (destFormat)
	{
	case HapTextureFormat_RGB_DXT1:
		return std::make_unique<SquishTextureConverter>(frameSize, squish::kDxt1 | flag_quality);
	case HapTextureFormat_RGBA_DXT5:
		return std::make_unique<SquishTextureConverter>(frameSize, squish::kDxt5 | flag_quality);
	case HapTextureFormat_YCoCg_DXT5:
		return std::make_unique<TextureConverterToYCoCg_Dxt5>(frameSize);
	case HapTextureFormat_A_RGTC1:
		return std::make_unique<SquishTextureConverter>(frameSize, squish::kRgtc1A);
	case HapTextureFormat_RGBA_BPTC_UNORM:
		return std::make_unique<TextureConverterToBC7>(frameSize, quality);
	default:
		throw std::runtime_error("unknown conversion");
	}
}


void TextureConverter::convert(const uint8_t* in_rgba,
							   std::vector<uint8_t> &intermediate_ycocg,
							   std::vector<uint8_t> &outputBuffer)
{
	doConvert(in_rgba, intermediate_ycocg, outputBuffer);
	if (qualityReportEnabled())
		accumulateQuality(format_, frameSize_.width, frameSize_.height, in_rgba, outputBuffer.data());
}


void TextureConverter::doConvert(
	const uint8_t* in_rgba,
	std::vector<uint8_t> &intermediate_ycocg,
	std::vector<uint8_t> &outputBuffer)
{
}